//! Original AEFB30 voice retirement, B141F0 last binding and owned node cleanup.
use crate::{audio_bus_bank::Error,audio_plugin_factory::Memory,audio_path_voice_configuration::Runtime,audio_path_manager};
fn word(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn set(b:&mut[u8],o:usize,v:u32){b[o..o+4].copy_from_slice(&v.to_le_bytes());}
pub trait Services:audio_path_manager::Disposal{
 fn dispatch_retirement(&mut self,voice:&mut Memory)->Result<(),Error>;
 fn release_owner(&mut self,owner:u32,voice_interface:u32)->Result<(),Error>;
 fn observe_dispatch_retirement(&mut self,_voice:&Memory){}
 fn observe_owner_release(&mut self,_owner:u32,_interface:u32){}
 fn observe_voice_and_resource(&mut self,_voice:&Memory,_resource:Option<&Memory>){}
}
pub fn retire(context:&mut Runtime,voice:&mut Memory,mode:u32,suppress_callback:bool,manager:&audio_path_manager::Runtime,services:&mut impl Services)->Result<(),Error>{
 if voice.reference==0||voice.raw.len()<408{return Err(Error::InvalidAllocation);}if voice.raw[301]&0x10!=0{return Ok(());}voice.raw[301]|=0x10;
 if !suppress_callback{services.dispatch_retirement(voice)?;}if mode!=0&&mode!=2{return Ok(());}
 for offset in [80,84]{let owner=word(&voice.raw,offset);if owner!=0{services.observe_voice_and_resource(voice,None);services.release_owner(owner,voice.reference.wrapping_add(8))?;set(&mut voice.raw,offset,0);}}
 let node=word(&voice.raw,400);if node!=0{let n=context.nodes.nodes.get(&node).ok_or(Error::UnresolvedReference)?;if n.reference!=node||n.raw.len()<28{return Err(Error::InvalidAllocation);}let mut resource_reference=None;
 if word(&n.raw,24)&2!=0{let state=crate::audio_path_source_state::nearest(&context.sources,word(&voice.raw,96))?;let reference=state.wrapping_sub(64);let resource=context.resources.get_mut(&reference).ok_or(Error::UnresolvedReference)?;if resource.reference!=reference||resource.raw.len()<72{return Err(Error::InvalidAllocation);}resource.raw[64..72].fill(0);resource_reference=Some(reference);}
 services.observe_voice_and_resource(voice,resource_reference.and_then(|r|context.resources.get(&r)));
 manager.remove_binding(&mut context.nodes,&mut context.bindings,&mut context.selection,&mut context.lifetime,node,voice.reference,services)?;set(&mut voice.raw,400,0);set(&mut voice.raw,404,0);
 }voice.raw[301]=(voice.raw[301]&!1)|4;Ok(())
}
struct OwnedReferences<'a,S>{owners:&'a mut crate::audio_path_voice_owner_release::Runtime,downstream:&'a mut S}
impl<S:Services> audio_path_manager::Services for OwnedReferences<'_,S>{fn allocate(&mut self,pool:u32,bytes:u32)->Result<Option<Memory>,Error>{self.downstream.allocate(pool,bytes)}fn free(&mut self,pool:u32,m:&Memory)->Result<(),Error>{self.downstream.free(pool,m)}fn observe_empty_destructor(&mut self,reference:u32){self.downstream.observe_empty_destructor(reference);}}
impl<S:Services> audio_path_manager::Disposal for OwnedReferences<'_,S>{fn observe_manager(&mut self,h:&[u8;12],t:&Memory){self.downstream.observe_manager(h,t);}fn observe_node_retirement(&mut self,raw:&[u8]){self.downstream.observe_node_retirement(raw);}}
impl<S:Services> Services for OwnedReferences<'_,S>{fn dispatch_retirement(&mut self,voice:&mut Memory)->Result<(),Error>{self.downstream.dispatch_retirement(voice)}fn release_owner(&mut self,owner:u32,interface:u32)->Result<(),Error>{self.downstream.observe_owner_release(owner,interface);self.owners.remove(owner,interface)?;Ok(())}fn observe_voice_and_resource(&mut self,voice:&Memory,resource:Option<&Memory>){self.downstream.observe_voice_and_resource(voice,resource);}}
/// Original caller with actual owned AF5B90 body; notification remains mandatory.
pub fn retire_owned_references(context:&mut Runtime,voice:&mut Memory,mode:u32,suppress_callback:bool,manager:&audio_path_manager::Runtime,owners:&mut crate::audio_path_voice_owner_release::Runtime,services:&mut impl Services)->Result<(),Error>{retire(context,voice,mode,suppress_callback,manager,&mut OwnedReferences{owners,downstream:services})}
struct NativeNotification<'a,S>{queue:&'a mut crate::audio_path_voice_notification::Runtime,frame:u32,downstream:&'a mut S}
impl<S:Services+crate::audio_path_voice_notification::Services> audio_path_manager::Services for NativeNotification<'_,S>{fn allocate(&mut self,p:u32,b:u32)->Result<Option<Memory>,Error>{self.downstream.allocate(p,b)}fn free(&mut self,p:u32,m:&Memory)->Result<(),Error>{self.downstream.free(p,m)}fn observe_empty_destructor(&mut self,r:u32){self.downstream.observe_empty_destructor(r);}}
impl<S:Services+crate::audio_path_voice_notification::Services> audio_path_manager::Disposal for NativeNotification<'_,S>{fn observe_manager(&mut self,h:&[u8;12],t:&Memory){self.downstream.observe_manager(h,t);}fn observe_node_retirement(&mut self,r:&[u8]){self.downstream.observe_node_retirement(r);}}
impl<S:Services+crate::audio_path_voice_notification::Services> Services for NativeNotification<'_,S>{fn dispatch_retirement(&mut self,voice:&mut Memory)->Result<(),Error>{self.downstream.observe_dispatch_retirement(voice);self.queue.notify(voice,self.frame,self.downstream)?;Ok(())}fn release_owner(&mut self,o:u32,i:u32)->Result<(),Error>{self.downstream.release_owner(o,i)}fn observe_owner_release(&mut self,o:u32,i:u32){self.downstream.observe_owner_release(o,i);}fn observe_voice_and_resource(&mut self,v:&Memory,r:Option<&Memory>){self.downstream.observe_voice_and_resource(v,r);}}
/// Retirement composes actual notification, owner reference and last-node bodies.
pub fn retire_notifying_owned_references(context:&mut Runtime,voice:&mut Memory,mode:u32,suppress_callback:bool,manager:&audio_path_manager::Runtime,owners:&mut crate::audio_path_voice_owner_release::Runtime,queue:&mut crate::audio_path_voice_notification::Runtime,frame:u32,services:&mut (impl Services+crate::audio_path_voice_notification::Services))->Result<(),Error>{retire_owned_references(context,voice,mode,suppress_callback,manager,owners,&mut NativeNotification{queue,frame,downstream:services})}
