 for a in b["allocations"].as_array().unwrap(){let reference=a["reference"].as_u64().unwrap()as u32;let m=Memory{reference,raw:bytes(a["raw"].as_str().unwrap())};match reference{0x40008000=>{context.nodes.nodes.insert(reference,m);},0x40009000=>{context.bindings.tables.insert(reference,m);},0x4000a000=>{context.selection.masks.insert(reference,m);},0x4000b000=>{context.lifetime.auxiliary.insert(reference,m);},_=>panic!("unexpected native allocation")}}
 let mut voice=Memory{reference:0x4000e000,raw:bytes(b["voice"].as_str().unwrap())};let mut backend=Backend{pattern:row["pattern"].as_u64().unwrap()as u8,calls:vec![],freed:BTreeMap::new(),order:vec![],manager:raw,table:context.nodes.table.raw.clone(),voice:voice.raw.clone(),resource:context.resources[&0x4000d000].raw.clone()};let memory_map=|v:&Value|v.as_array().unwrap().iter().map(|m|{let reference=m["reference"].as_u64().unwrap()as u32;(reference,Memory{reference,raw:bytes(m["raw"].as_str().unwrap())})}).collect();let mut owners=if owned{crate::audio_path_voice_owner_release::Runtime{owners:memory_map(&b["owners"]),tables:memory_map(&b["owner_tables"])}}else{crate::audio_path_voice_owner_release::Runtime::default()};let manager=audio_path_manager::Runtime{limit:4,pool:17};let mode=row["mode"].as_u64().unwrap()as u32;let suppress=row["suppress_callback"].as_bool().unwrap_or(true);let mut queue=crate::audio_path_voice_notification::Runtime{header:if notifying{bytes(b["notification_queue"].as_str().unwrap()).try_into().unwrap()}else{[0;28]},regions:BTreeMap::new(),freed_nodes:std::collections::BTreeSet::new(),pool:17};if notifying{retire_notifying_owned_references(&mut context,&mut voice,mode,suppress,&manager,&mut owners,&mut queue,0x12345678,&mut backend).unwrap();}else if owned{retire_owned_references(&mut context,&mut voice,mode,suppress,&manager,&mut owners,&mut backend).unwrap();}else{retire(&mut context,&mut voice,mode,suppress,&manager,&mut backend).unwrap();}assert_eq!(json!(backend.calls),row["calls"],"ordered physical calls and state at free {i}");assert_eq!(json!(backend.order),row["freed"],"free order {i}");
 let allocations:Vec<Value>=b["allocations"].as_array().unwrap().iter().map(|a|{let reference=a["reference"].as_u64().unwrap()as u32;let m=backend.freed.get(&reference).or_else(||context.nodes.nodes.get(&reference)).or_else(||context.bindings.tables.get(&reference)).or_else(||context.selection.masks.get(&reference)).or_else(||context.lifetime.auxiliary.get(&reference)).unwrap();json!({"reference":reference,"size":m.raw.len(),"raw":hex(&m.raw),"freed":backend.freed.contains_key(&reference)})}).collect();let mut manager=context.nodes.header.to_vec();manager.extend_from_slice(&4u32.to_le_bytes());let sources:Vec<Value>=context.sources.values().map(|m|json!({"reference":m.reference,"raw":hex(&m.raw)})).collect();let mut after=json!({"voice":hex(&voice.raw),"source_chain":sources,"resource":hex(&context.resources[&0x4000d000].raw),"manager":hex(&manager),"table":hex(&context.nodes.table.raw),"allocations":allocations});if owned{after["owners"]=json!(owners.owners.values().map(|m|json!({"reference":m.reference,"raw":hex(&m.raw)})).collect::<Vec<_>>());after["owner_tables"]=json!(owners.tables.values().map(|m|json!({"reference":m.reference,"raw":hex(&m.raw)})).collect::<Vec<_>>());}if notifying{after["notification_queue"]=json!(hex(&queue.header));after["notification_node"]=json!(queue.regions.get(&0x40006000).map(|m|hex(&m.raw)).unwrap_or_else(||b["notification_node"].as_str().unwrap().to_string()));}assert_eq!(after,row["after"],"complete424-byte voice, borrowed state and allocation ownership {i}");
